// Общие шаги для тестов «מחשבון כדאיות רכישת עסק» (#3e4835, #80ff63, #22ce3e, #d4f37b; PR #181).
// Прод, только чтение: калькулятор считает в браузере; не-GET запросы обрываются, баннер cookie закрыт заранее.
import { expect, BrowserContext, Page } from '@playwright/test';

export const LOAD = { timeout: 25_000 };
/** Прогоны: десктоп и Android (Pixel 7) — по сценарию тикетов. Пометка в названии выбирает проект в playwright.config.ts. */
export const DEVICES = ['@desktop', '@android'] as const;

const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];

export type CalcInput =
  | 'purchasePrice'
  | 'setupCosts'
  | 'inventory'
  | 'reserve'
  | 'loanAmount'
  | 'monthlyProfit'
  | 'ownerSalary'
  | 'monthlyLoanPayment';

/** Набор 1 из проверки (налог по умолчанию 23%). */
export const SET1: Record<CalcInput, string> = {
  purchasePrice: '500000',
  setupCosts: '50000',
  inventory: '30000',
  reserve: '20000',
  loanAmount: '200000',
  monthlyProfit: '40000',
  ownerSalary: '15000',
  monthlyLoanPayment: '5000',
};

export const field = (page: Page, name: CalcInput) => page.locator(`#calc-${name}`);

/** Убрать направляющие метки (RLM/LRM/embedding) и неразрывные пробелы, схлопнуть пробелы. */
export function norm(s: string): string {
  return s
    .replace(/[‎‏‪-‮⁦-⁩]/g, '')
    .replace(/ /g, ' ')
    .replace(/[ \t]+/g, ' ')
    .trim();
}

/** Вызывать до первого перехода: не-GET обрываются, cookie — «только необходимые». */
export async function prepareReadOnly(context: BrowserContext) {
  await context.route('**/*', (route) =>
    SAFE_METHODS.includes(route.request().method()) ? route.fallback() : route.abort('blockedbyclient'),
  );
  await context.addInitScript(() => {
    try {
      if (!localStorage.getItem('cookie-consent-v2')) {
        localStorage.setItem(
          'cookie-consent-v2',
          JSON.stringify({ essential: true, performance: false, marketing: false, updatedAt: new Date().toISOString() }),
        );
      }
    } catch {}
  });
}

export async function openCalculator(page: Page) {
  await page.goto('/calculator');
  await expect(field(page, 'purchasePrice')).toBeVisible(LOAD);
}

export async function fillInputs(page: Page, values: Partial<Record<CalcInput, string>>) {
  for (const [name, value] of Object.entries(values)) await field(page, name as CalcInput).fill(value!);
}

/**
 * Значение результата по подписи в блоке «תוצאות» (подпись и значение — соседние элементы).
 * Ищем внутри контейнера, где есть и заголовок «תוצאות», и кнопка «העתקת סיכום».
 */
export async function resultValue(page: Page, label: string): Promise<string | null> {
  const raw = await page.evaluate((lbl) => {
    const heading = document.getElementById('calc-results-heading');
    let box: HTMLElement | null = heading;
    while (box && !Array.from(box.querySelectorAll('button')).some((b) => b.textContent?.includes('העתקת סיכום'))) {
      box = box.parentElement;
    }
    if (!box) return null;
    const el = Array.from(box.querySelectorAll<HTMLElement>('*')).find(
      (e) => e.children.length === 0 && (e.textContent || '').trim() === lbl && e.nextElementSibling,
    );
    return el ? (el.nextElementSibling as HTMLElement).innerText : null;
  }, label);
  return raw === null ? null : norm(raw);
}

/** Ждать, пока результат станет ожидаемым (пересчёт без кнопки — сразу после ввода). */
export async function expectResult(page: Page, label: string, expected: string) {
  await expect.poll(() => resultValue(page, label), { message: `«${label}» = ${expected}` }).toBe(expected);
}

/** Текст, который «העתקת סיכום» кладёт в буфер (Chromium; разрешения выдаются в тесте). */
export async function copySummary(page: Page): Promise<string> {
  await page.getByRole('button', { name: 'העתקת סיכום' }).click();
  await expect(page.getByText('הסיכום הועתק'), 'тост «הסיכום הועתק»').toBeVisible();
  return norm(await page.evaluate(() => navigator.clipboard.readText()));
}
